## 6. Implementation Details

### 6.1 Formatter Registration
```ts
function registerFormatters(
  editor: Editor,
  prefix: string,
  overrides: Record<string, Partial<FormatConfig>>
): void {
  const merged = { ...DEFAULT_FORMATS };

  // Apply user overrides
  for (const [name, config] of Object.entries(overrides)) {
    merged[name] = { ...merged[name], ...config };
  }

  // Register each format
  for (const [name, config] of Object.entries(merged)) {
    const fullyQualifiedConfig = buildFormatSpec(name, config, prefix);
    editor.formatter.register(name, fullyQualifiedConfig);
  }
}

function buildFormatSpec(
  formatName: string,
  config: FormatConfig,
  prefix: string
): any {  // TinyMCE formatter spec object
  const classes = config.classes?.map(cls => cls.startsWith(prefix) ? cls : `${prefix}-${cls}`) ?? [];

  const spec: any = {
    classes,
  };

  if (config.element) spec.element = config.element;
  if (config.styles) spec.styles = config.styles;
  if (config.attributes) spec.attributes = config.attributes;

  return spec;
}
```

### 6.2 Event Listeners for Insertions (Link, Image, Table)
```ts
function setupPostProcessors(editor: Editor, prefix: string, options: FormatsPluginOptions): void {
  editor.on('ExecCommand', (e) => {
    if (e.command === 'CreateLink') {
      const link = editor.dom.getParent(editor.selection.getNode(), 'a');
      if (link) {
        editor.dom.addClass(link, `${prefix}-link`);
        options.onApply?.(link, 'link');
      }
    }
    if (e.command === 'mceInsertImage') {
      const img = editor.dom.select('img[data-mce-selected]')[0];
      if (img) {
        editor.dom.addClass(img, `${prefix}-img`);
        options.onApply?.(img, 'image');
      }
    }
    if (e.command === 'mceInsertTable') {
      const table = editor.dom.select('table[data-mce-selected]')[0];
      if (table) {
        editor.dom.addClass(table, `${prefix}-table`);
        for (const row of editor.dom.select('tr', table)) {
          editor.dom.addClass(row, `${prefix}-table-row`);
        }
        for (const cell of editor.dom.select('td,th', table)) {
          editor.dom.addClass(cell, `${prefix}-table-cell`);
        }
        options.onApply?.(table, 'table');
      }
    }
  });
}
```

### 6.3 Plugin Main Function
```ts
export function createFormatsPlugin(options?: FormatsPluginOptions): (editor: Editor) => void {
  return function pantokenFormatsPlugin(editor: Editor) {
    const prefix = options?.prefix ?? 'instui';
    const formatOverrides = options?.formats ?? {};

    // Register formatters
    registerFormatters(editor, prefix, formatOverrides);

    // Set up post-processors for insertions
    setupPostProcessors(editor, prefix, options ?? {});

    // No toolbar button (registerUi is a no-op for this plugin)
  };
}
```

